/// Identifies the code path that is acquiring the layer manager lock.
///
/// This is used for observability and debugging of lock contention: every caller of
/// [`LockedLayerManager::read`]/[`LockedLayerManager::write`] (and their `try_` variants) must
/// declare who they are.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum LayerManagerLockHolder {
    /// Used in test code.
    Testing,
    /// Reading layer map metadata for the HTTP API and similar introspection.
    GetLayerMapInfo,
    /// Generating a heatmap of the layers.
    GenerateHeatmap,
    /// Serving a page read request.
    GetPage,
    /// Initializing the layer map (loading it from local/remote storage).
    Init,
    /// Opening or looking up the layer to write into.
    GetLayerForWrite,
    /// Freezing the open in-memory layer.
    TryFreezeLayer,
    /// Flushing a frozen in-memory layer to disk.
    FlushFrozenLayer,
    /// Compaction (including image layer creation).
    Compaction,
    /// Garbage collection.
    GarbageCollection,
    /// Eviction of on-disk layers.
    Eviction,
    /// Detaching a timeline from its ancestor.
    DetachAncestor,
    /// Importing data via pgdata import.
    ImportPgData,
    /// Timeline shutdown.
    Shutdown,
}

/// Read guard returned by [`LockedLayerManager::read`].
pub(crate) type LayerManagerReadGuard<'a> = tokio::sync::RwLockReadGuard<'a, LayerManager>;

/// Write guard returned by [`LockedLayerManager::write`].
pub(crate) type LayerManagerWriteGuard<'a> = tokio::sync::RwLockWriteGuard<'a, LayerManager>;

/// A lock around a [`LayerManager`] that requires callers to identify themselves via a
/// [`LayerManagerLockHolder`] when acquiring the lock.
#[derive(Default)]
pub(crate) struct LockedLayerManager {
    locked: tokio::sync::RwLock<LayerManager>,
}

impl LockedLayerManager {
    /// Acquire a shared read lock on the layer manager.
    pub(crate) async fn read(
        &self,
        _holder: LayerManagerLockHolder,
    ) -> LayerManagerReadGuard<'_> {
        self.locked.read().await
    }

    /// Try to acquire a shared read lock on the layer manager without waiting.
    pub(crate) fn try_read(
        &self,
        _holder: LayerManagerLockHolder,
    ) -> Result<LayerManagerReadGuard<'_>, tokio::sync::TryLockError> {
        self.locked.try_read()
    }

    /// Acquire an exclusive write lock on the layer manager.
    pub(crate) async fn write(
        &self,
        _holder: LayerManagerLockHolder,
    ) -> LayerManagerWriteGuard<'_> {
        self.locked.write().await
    }

    /// Try to acquire an exclusive write lock on the layer manager without waiting.
    pub(crate) fn try_write(
        &self,
        _holder: LayerManagerLockHolder,
    ) -> Result<LayerManagerWriteGuard<'_>, tokio::sync::TryLockError> {
        self.locked.try_write()
    }
}

